const app=document.querySelector('#app');let screen='landing',answers=Array(10).fill(''),tags=new Set(),image=null,result=null,isDemo=false,busy=false;const questions=['Любимые фильмы или сериалы','Любимые книги','Любимая музыка: исполнители или жанры','Любимое хобби','Любимые города и страны','Любимый цвет','Что ты выбираешь снова и снова: вещи, бренды, еда, места','Что тебе нравится делать на работе','Люди, за которыми тебе интересно следить','Что ещё ты любишь?'];const examples=['Шрек 2, Наследники, Сумерки','Гарри Поттер, Сто лет одиночества, Дневник Бриджит Джонс','Земфира, Lana Del Rey, техно','керамика, бег, танцы на кухне','Лиссабон, Италия, Япония','бордовый, чёрный, цвет морской волны','водолазки, Zara, матча, ИКЕА в субботу утром','Можно добавить свой вариант','Рианна, Стив Джобс, моя бабушка','Всё, что не влезло выше. Можно списком или скрином.'];const workTags=['придумывать новое','разбираться','наводить порядок','строить систему','убеждать','работать с людьми','руководить','выступать','делать красиво','решать сложное','начинать с нуля','улучшать существующее'];const demo={main_insight:'Ты снова и снова выбираешь вещи, где маленькие действия постепенно собирают целый мир.',areas_count:6,patterns:[{title:'Шаги → мир',description:'Мир становится больше от небольших действий, которые хочется повторять.',evidence:[{item:'Stardew Valley',reason:'Ферма растёт от ежедневных посадок, ухода и небольших улучшений.'},{item:'Огород на балконе',reason:'Каждый полив и новый росток постепенно меняют пространство.'},{item:'Lego',reason:'Из отдельных деталей шаг за шагом возникает целая конструкция.'}]},{title:'Детали → порядок',description:'Отдельные части складываются в понятную систему, которой можно пользоваться.',evidence:[{item:'IKEA',reason:'Модули и вещи можно собрать в собственный работающий быт.'},{item:'Таблицы для всего',reason:'Каждая запись становится частью обозримой системы.'},{item:'Наводить порядок',reason:'Разрозненные вещи получают место и связь друг с другом.'}]},{title:'Возвращение → продолжение',description:'Знакомое пространство каждый раз даёт повод заметить ещё одну деталь.',evidence:[{item:'Гарри Поттер',reason:'При перечитывании знакомого мира раскрываются пропущенные детали.'},{item:'Stardew Valley',reason:'Возвращение к ферме продолжает уже начатую историю.'},{item:'Огород на балконе',reason:'Ежедневное возвращение позволяет наблюдать новые изменения.'}]}],unexpected_connections:[{item_1:'Stardew Valley',item_2:'Огород на балконе',connection:'В обоих маленькая ежедневная забота превращается в видимый рост.'},{item_1:'Lego',item_2:'Таблицы для всего',connection:'Отдельные элементы обретают смысл, когда собираются в целую систему.'},{item_1:'Гарри Поттер',item_2:'IKEA',connection:'Детали складываются в пространство, которое хочется изучать и обживать.'}],same_reason:[{item:'Сад в бутылке',pattern:'Шаги → мир: маленькая экосистема растёт от регулярной заботы.'},{item:'Townscaper',pattern:'Детали → порядок: город складывается из отдельных построек.'},{item:'«Тайный сад»',pattern:'Возвращение → продолжение: знакомое место постепенно оживает.'}]};
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function count(){return answers.reduce((n,a)=>n+a.split(/[,;\n]+/).map(s=>s.trim()).filter(Boolean).length,0)+tags.size}function go(s){if(busy)return;screen=s;render();window.scrollTo(0,0);app.querySelector('h1,h2')?.setAttribute('tabindex','-1');app.querySelector('h1,h2')?.focus({preventScroll:true})}function badge(){return isDemo?'<div class="demo">Пример результата · не анализ твоих ответов</div>':''}function step(next,label){return `<div class="stepnav"><button class="back" onclick="go('${screen==='patterns'?'insight':screen==='pairs'?'patterns':screen==='recommendations'?'pairs':'recommendations'}')">Назад</button><button class="primary" onclick="go('${next}')">${label}</button></div>`}
function render(){if(screen==='landing'){app.innerHTML=`<section class="landing"><div><div class="eyebrow">То, что связывает любимое</div><h1>Между<br><em>строк</em></h1><p class="subtitle">Напиши, что любишь.<br>Посмотри, что повторяется.</p><button class="primary" onclick="go('form')">Найти связи</button><button class="secondary samplelink" onclick="showDemo()">Посмотреть пример</button></div><aside class="composition"><div class="quote serif">Вещи разные.<br>Что-то между<br>ними — общее.</div><div class="pair-preview"><span>Stardew Valley</span><span>↔</span><span>Огород на балконе</span></div><p class="small">Маленькая ежедневная забота → видимый рост.<br>Пара из примера результата.</p></aside></section>`;return}if(screen==='form'){app.innerHTML=`<section class="page narrow"><div class="topline"><div class="eyebrow">01 / Твои выборы</div><button class="back" onclick="go('landing')">На главную</button></div><h2>У твоих выборов<br><i>есть общая история.</i></h2><p class="form-lead serif">Иногда любимый фильм, город и цвет рассказывают одну историю. Посмотрим, что связывает твои выборы.</p><p class="intro">Чем честнее ответы, тем интереснее результат. Пиши сколько хочешь. Вопросы можно пропускать.</p><form id="answers-form">${questions.map((q,i)=>`<div class="field"><label for="answer-${i}"><b>${String(i+1).padStart(2,'0')}</b>${q}</label>${i===7?`<div class="tags">${workTags.map((t,k)=>`<button type="button" class="tag" data-tag="${k}" aria-pressed="${tags.has(t)}">${t}</button>`).join('')}</div>`:''}<textarea id="answer-${i}" data-index="${i}" placeholder="${examples[i]}">${esc(answers[i])}</textarea>${i===9?'<label class="upload" for="screenshot">Добавить скриншот <span class="small">· PNG, JPEG или WebP, до 5 МБ</span><input type="file" id="screenshot" accept="image/png,image/jpeg,image/webp"></label><div id="image-status" class="small"></div>':''}</div>`).join('')}<div id="error" class="error" role="alert"></div><div class="form-bottom"><div class="count"><span id="count">${count()}</span> вещей <span class="small">/ минимум 12</span><br><span class="small">Лучше 20–30 из разных сфер</span></div><button type="submit" class="primary">Найти связи</button></div></form></section>`;app.querySelectorAll('textarea').forEach(el=>el.addEventListener('input',()=>{answers[+el.dataset.index]=el.value;document.querySelector('#count').textContent=count()}));app.querySelectorAll('[data-tag]').forEach(el=>el.onclick=()=>{let t=workTags[+el.dataset.tag];tags.has(t)?tags.delete(t):tags.add(t);el.setAttribute('aria-pressed',tags.has(t));document.querySelector('#count').textContent=count()});document.querySelector('#screenshot').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)){document.querySelector('#image-status').textContent='Нужен PNG, JPEG или WebP до 5 МБ.';e.target.value='';return}image=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});document.querySelector('#image-status').textContent=`Добавлен: ${f.name}. Названия будут распознаны при анализе.`};document.querySelector('#answers-form').onsubmit=e=>{e.preventDefault();analyze()};return}if(screen==='loading'){app.innerHTML='<section class="page focus"><div class="loading"></div><div class="eyebrow">Между строк</div><h2>Ищем то,<br><i>что повторяется.</i></h2><p class="intro" style="margin:0 auto">Сначала находим связи в твоих выборах.<br>Затем проверяем, чем каждая подтверждается.</p><p class="small">Обычно это занимает около минуты.</p></section>';return}if(!result){go('form');return}if(screen==='insight'){app.innerHTML=`<section class="page focus">${badge()}<div class="eyebrow">Между строк</div><h2 class="insight">${esc(result.main_insight)}</h2><p class="small">Это повторилось в ${result.areas_count} сферах твоих выборов.</p><button class="primary" onclick="go('patterns')">Как это связано</button><button class="back" style="margin-top:20px" onclick="go('form')">Вернуться к ответам</button></section>`;return}if(screen==='patterns'){app.innerHTML=`<section class="page">${badge()}<div class="eyebrow">02 / Паттерны</div><h2>Одна связь.<br><i>Разные проявления.</i></h2><div class="cards">${result.patterns.map((p,i)=>`<article class="card"><span class="num">0${i+1}</span><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="evidence">${p.evidence.map(e=>`<details><summary>${esc(e.item)}</summary><p>${esc(e.reason)}</p></details>`).join('')}</div></article>`).join('')}</div>${step('pairs','Неожиданные пары')}</section>`;return}if(screen==='pairs'){app.innerHTML=`<section class="page">${badge()}<div class="eyebrow">03 / Неожиданные пары</div><h2>Вещи, которые тебе нравятся<br><i>по одной причине.</i></h2>${result.unexpected_connections.map(p=>`<article class="connection"><div class="pair">${esc(p.item_1)} <span>↔</span> ${esc(p.item_2)}</div><p>${esc(p.connection)}</p></article>`).join('')}${step('recommendations','Что ещё может понравиться')}</section>`;return}if(screen==='recommendations'){app.innerHTML=`<section class="page">${badge()}<div class="eyebrow">04 / Продолжение</div><h2>По той же причине<br><i>тебе может понравиться.</i></h2><p class="intro">Три предположения. Попробуй и посмотри, отзывается ли связь.</p><div class="cards">${result.same_reason.map((p,i)=>`<article class="card"><span class="num">0${i+1}</span><h3>${esc(p.item)}</h3><p>${esc(p.pattern)}</p></article>`).join('')}</div>${step('share','Собрать карточку')}</section>`;return}if(screen==='share'){app.innerHTML=`<section class="page share-wrap"><canvas id="share" width="1080" height="1350" aria-label="Карточка результата"></canvas><div class="share-actions">${badge()}<div class="eyebrow">05 / С собой</div><h2>Сохрани<br><i>между строк.</i></h2><p class="intro">Главная фраза, три паттерна и неожиданные пары — в одной карточке.</p><button class="primary" onclick="download()">Скачать карточку</button><button class="secondary" onclick="shareCard()">Поделиться</button><p id="share-status" class="small" role="status"></p><button class="back" onclick="go('recommendations')">Назад к результату</button></div></section>`;drawCard()}}
function showDemo(){isDemo=true;result=structuredClone(demo);go('insight')}async function analyze(){const e=document.querySelector('#error');if(count()<12&&!image){e.textContent='Добавь ещё '+(12-count())+' вещей. Разделяй названия запятыми или новой строкой.';return}busy=true;screen='loading';render();window.scrollTo(0,0);try{const response=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({answers:answers.map((a,i)=>({area:questions[i],items:i===7?[a,...tags].filter(Boolean).join(', '):a})),image}),signal:AbortSignal.timeout(150000)});if(response.status===404||response.status===405)throw new Error('AI-анализ ещё не подключён. Пока можно посмотреть пример с главной страницы.');if(!response.ok){let body=await response.json().catch(()=>({}));throw new Error(body.error||'Не удалось выполнить анализ. Попробуй ещё раз.')}result=await response.json();isDemo=false;busy=false;go('insight')}catch(err){busy=false;go('form');document.querySelector('#error').textContent=err.name==='TimeoutError'?'Анализ занял слишком много времени. Попробуй ещё раз.':err.message}}
function drawCard(){const c=document.querySelector('#share'),x=c.getContext('2d');x.fillStyle='#efe9df';x.fillRect(0,0,1080,1350);x.strokeStyle='#cec5b8';x.strokeRect(52,52,976,1246);x.fillStyle='#782c36';x.font='24px Manrope, Arial';x.fillText('М Е Ж Д У  С Т Р О К',85,125);let y=210;function wrap(t,size,width,color,maxLines=10){x.fillStyle=color;x.font=`${size}px ${size>36?'"Cormorant Garamond",Georgia':'Manrope,Arial'}`;const words=t.split(' ');let line='',lines=[];for(const w of words){if(x.measureText(line+w).width>width&&line){lines.push(line.trim());line=w+' '}else line+=w+' '}if(line)lines.push(line.trim());if(lines.length>maxLines){lines=lines.slice(0,maxLines);lines[maxLines-1]=lines[maxLines-1].slice(0,-2)+'…'}for(const l of lines){x.fillText(l,85,y);y+=size*1.13}return y}if(isDemo){x.font='20px Arial';x.fillStyle='#777268';x.fillText('ПРИМЕР РЕЗУЛЬТАТА',85,163)}wrap(result.main_insight,68,900,'#947338',5);y=Math.max(610,y+40);x.strokeStyle='#cec5b8';x.beginPath();x.moveTo(85,y);x.lineTo(995,y);x.stroke();y+=60;result.patterns.forEach((p,i)=>{wrap(`0${i+1}   ${p.title}`,34,900,'#24231f',1);y+=12});y+=32;result.unexpected_connections.forEach(p=>{wrap(`${p.item_1} ↔ ${p.item_2}`,29,900,'#782c36',2);y+=18});x.fillStyle='#777268';x.font='22px Manrope,Arial';x.fillText('Что повторяется в моих выборах',85,1230);x.font='18px Manrope,Arial';x.fillText('Между строк · '+(location.protocol==='file:'?'':location.host),85,1270)}async function cardBlob(){await document.fonts.ready;drawCard();return new Promise(r=>document.querySelector('#share').toBlob(r,'image/png'))}async function download(){const blob=await cardBlob();let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mezhdu-strok.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}async function shareCard(){const blob=await cardBlob(),file=new File([blob],'mezhdu-strok.png',{type:'image/png'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Между строк'});return}await download();document.querySelector('#share-status').textContent='Карточка скачана — её можно отправить в любом приложении.'}catch(e){if(e.name!=='AbortError')document.querySelector('#share-status').textContent='Не удалось поделиться. Попробуй скачать карточку.'}}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'stage_preferences',description:'Заполнить ответы и открыть форму, без запуска анализа.',inputSchema:{type:'object',properties:{answers:{type:'array',items:{type:'string'},minItems:10,maxItems:10}},required:['answers'],additionalProperties:false},execute(input){if(!Array.isArray(input.answers)||input.answers.length!==10||input.answers.some(v=>typeof v!=='string'||v.length>4000))throw new Error('Нужно десять текстовых ответов');answers=[...input.answers];go('form');return{things_count:count(),screen}},annotations:{readOnlyHint:false,untrustedContentHint:false}})}catch{}}
render();
